CREATE VIEW vw_recommendation_engine_summary AS (SELECT 'Taste Affinity' AS component, '50% explicit preference percentile + 50% learned similarity percentile' AS logic, 'Primary preference-fit signal' AS "role") UNION ALL ((((SELECT 'Conditional Affinity', 'Activated only when playability risk exists and mitigation is available', 'Supports conditional favorites such as Souls-like games with mitigation') UNION ALL (SELECT 'Playability', 'Hard exclusions plus control, SHMUP, Souls-like, and mitigation rules', 'Determines practical playability and conditional status')) UNION ALL ((SELECT 'Quality', '(Quality Percentile - 50) × 0.10', 'Small secondary modifier / tiebreaker') UNION ALL (SELECT 'Recommendation Context', 'Separates playable backlog, currently playing, owned-status-unknown, discovery, completed, and unavailable', 'Determines recommendation purpose'))) UNION ALL ((SELECT 'Play Next', 'Owned + available + canonical Unplayed + non-seed + non-excluded', 'Actionable backlog recommendation mart') UNION ALL (SELECT 'Discovery', 'Not owned / access unknown with valid recommendation score', 'Potential acquisition-interest mart')));
